        let other = &rows.last().unwrap().2;
        assert!(other.contains(&"README.md".to_string()) && !other.contains(&"docs/".to_string()), "{other:?}");
        // With none, Other files' level.
        let mut rest = Levels::new();
        rest.entry("code".into()).or_default().insert("rest".into(), Level::Read);
        save(docs(&[]), rest);
        assert_eq!(reached(ProfileKind::Code, Area::Added(0)), Some(Access::ReadOnly));
        // Suspense data is No access by default, a run's own files aside.
        assert_eq!(reached(ProfileKind::Code, Area::ProjectData), None);
        // Overlapping the code: refused.
        save(
            crate::sandbox::AddedArea {
                name: "Sources".into(),
                roots: vec!["src/inner".into()],
                ..crate::sandbox::AddedArea::default()
            },
            Levels::new(),
        );
        assert!(profile(ProfileKind::Code, crate::agent::Agent::Claude, &dir, &RunFiles::default()).is_err());
        std::fs::remove_dir_all(&dir).ok();
    }
}
