        level: Option<crate::sandbox::reach::Level>,
        cx: &mut Context<Self>,
    ) {
        use crate::sandbox::reach::{Area, Level, mode_key};
        let Some(project_dir) = ProjectDirectory::get(cx) else {
            return;
        };
        let store = |this: &mut Self, level: Option<Level>, cx: &mut Context<Self>| {
            this.classify(
                |classification| {
